import z3

# Parameters
num_golfers = 24
num_weeks = 8
num_groups = 8
group_size = 3

# Variables: group[w][g] = group assignment for golfer g in week w
group = [[z3.Int(f"group_{w}_{g}") for g in range(num_golfers)] for w in range(num_weeks)]

solver = z3.Solver()

# Each group variable ranges 0..7
for w in range(num_weeks):
    for g in range(num_golfers):
        solver.add(group[w][g] >= 0, group[w][g] < num_groups)

# Each group has exactly 3 golfers each week
for w in range(num_weeks):
    for k in range(num_groups):
        # Count how many golfers are in group k in week w
        solver.add(z3.PbEq([(group[w][g] == k, 1) for g in range(num_golfers)], group_size))

# No pair meets more than once
# For each pair (g1, g2), they can be in the same group at most once
for g1 in range(num_golfers):
    for g2 in range(g1+1, num_golfers):
        # Count weeks where they are in same group
        same_group = [group[w][g1] == group[w][g2] for w in range(num_weeks)]
        solver.add(z3.PbLe([(s, 1) for s in same_group], 1))

print("Constraints added. Solving...")
result = solver.check()
print("Result:", result)

if result == z3.sat:
    model = solver.model()
    # Extract solution
    solution = []
    for w in range(num_weeks):
        for g in range(num_golfers):
            solution.append(model.evaluate(group[w][g]).as_long())
    print("Solution:", solution)
    # Verify
    # Check group sizes
    for w in range(num_weeks):
        counts = [0]*num_groups
        for g in range(num_golfers):
            counts[solution[w*24+g]] += 1
        print(f"Week {w}: group counts {counts}")
    # Check pairs
    pair_weeks = {}
    for w in range(num_weeks):
        for k in range(num_groups):
            members = [g for g in range(num_golfers) if solution[w*24+g] == k]
            for i in range(len(members)):
                for j in range(i+1, len(members)):
                    pair = (members[i], members[j])
                    if pair in pair_weeks:
                        print(f"ERROR: pair {pair} meets in weeks {pair_weeks[pair]} and {w}")
                    pair_weeks[pair] = w
    print("All pairs checked.")
